function(){
   var val = this.value.replace(/\D/g, '');
   var newVal = '';
    if(val.length > 4) {
        this.value = val;
    }
    if((val.length > 2) && (val.length < 6)) {
        newVal += val.substr(0, 2) + '/';
        val = val.substr(2);
    }
    if (val.length > 5) {
        newVal += val.substr(0, 2) + '/';
        newVal += val.substr(2, 2) + '/';
        val = val.substr(4);
    }
    newVal += val;
    this.value = newVal;   
}

